// Channel constants - must match the Voice Router inside LLM Pipeline v3
const TWS_CHANNEL = 'UC9VKHMUGg5gqSebXW1m5GBw';
const HITPOINT_CHANNEL = 'UCyFDhiqKcVqoIGB3CmJJFUg';

const form = $input.first().json;

const rawVideo = (form['YouTube Video URL or ID'] || '').toString().trim();
const channelChoice = (form['Channel'] || '').toString().trim();
const transcript = (form['Transcript'] || '').toString().trim();

// Extract the 11-character YouTube video ID.
// Accepts: raw 11-char ID, youtube.com/watch?v=, youtu.be/, /live/ (also /shorts/, /embed/).
const RAW_ID = new RegExp('^[A-Za-z0-9_-]{11}$');
const URL_ID = new RegExp('(?:youtube[.]com/(?:watch[?](?:[^&]*&)*v=|live/|shorts/|embed/)|youtu[.]be/)([A-Za-z0-9_-]{11})');

let video_id = null;
if (RAW_ID.test(rawVideo)) {
  video_id = rawVideo;
} else {
  const m = rawVideo.match(URL_ID);
  if (m) video_id = m[1];
}
if (!video_id) {
  throw new Error('Could not read a YouTube video ID from "' + rawVideo + '". Paste a full YouTube URL (watch?v=, youtu.be/ or /live/) or the 11-character video ID.');
}

// Map the channel dropdown to its YouTube channel_id (drives the Voice Router in Stage 3).
const choice = channelChoice.toLowerCase();
let channel_id;
if (choice.indexOf('hitpoint') !== -1) {
  channel_id = HITPOINT_CHANNEL;
} else if (choice.indexOf('tws') !== -1) {
  channel_id = TWS_CHANNEL;
} else {
  throw new Error('Unknown channel "' + channelChoice + '". Choose TWS or Hitpoint.');
}

// Require a real transcript.
if (transcript.length <= 1000) {
  throw new Error('Transcript too short (' + transcript.length + ' chars) - paste the full transcript, minimum 1000 characters.');
}

return [{
  json: {
    video_id: video_id,
    transcript: transcript,
    chart_urls: [],
    channel_id: channel_id,
    source: 'manual_form'
  }
}];

// The Postgres RETURNING step outputs only { video_id, channel_id }.
// Re-emit the full Stage 3 contract { video_id, transcript, chart_urls, channel_id }
// (LLM Pipeline v3 expects the transcript) from the Prepare Manual Input node.
return $('Prepare Manual Input').all();
